{"code":"const testVision2 = await tools.bash({
  command: `mkdir -p .work_pdf/tmp .work_pdf/cache
env TMPDIR="$PWD/.work_pdf/tmp" \
    CLANG_MODULE_CACHE_PATH="$PWD/.work_pdf/cache" \
    SWIFT_MODULECACHE_PATH="$PWD/.work_pdf/cache" \
swift -module-cache-path "$PWD/.work_pdf/cache" - << 'EOF'
import Foundation
import Vision
import AppKit

let imageURL = URL(fileURLWithPath: ".work_pdf/page_016.png")
guard let image = NSImage(contentsOf: imageURL),
      let tiffData = image.tiffRepresentation,
      let bitmap = NSBitmapImageRep(data: tiffData),
      let cgImage = bitmap.cgImage else {
    print("Failed to load image")
    exit(1)
}

let request = VNRecognizeTextRequest { request, error in
    guard let observations = request.results as? [VNRecognizedTextObservation] else { return }
    // Sort observations top to bottom, left to right
    let sorted = observations.sorted { $0.boundingBox.origin.y > $1.boundingBox.origin.y }
    for obs in sorted {
        if let top = obs.topCandidates(1).first {
            let box = obs.boundingBox
            print(String(format: "y:%.3f x:%.3f | %@", box.origin.y, box.origin.x, top.string))
        }
    }
}
request.recognitionLanguages = ["zh-Hans", "en-US"]
request.recognitionLevel = .accurate
request.usesLanguageCorrection = true

let handler = VNImageRequestHandler(cgImage: cgImage, options: [:])
try handler.perform([request])
EOF
`,
  description: "Test Swift Vision OCR with proper cache path"
