swift -module-cache-path "$PWD/.work_pdf/cache" - << 'EOF'
import Foundation
import Vision
import AppKit

func ocr(page: Int) {
    let path = String(format: ".work_pdf/page_%03d.png", page)
    guard let image = NSImage(contentsOfFile: path),
          let tiff = image.tiffRepresentation,
          let rep = NSBitmapImageRep(data: tiff),
          let cg = rep.cgImage else {
        print("Cannot load \(path)")
        return
    }

    let req = VNRecognizeTextRequest()
    req.recognitionLanguages = ["zh-Hans", "en-US"]
    req.recognitionLevel = .accurate
    req.usesLanguageCorrection = false

    let handler = VNImageRequestHandler(cgImage: cg, options: [:])
    try? handler.perform([req])

    guard let results = req.results else { return }

    print("=================== PAGE \(page) ===================")
    // The page has two columns: left (x < 0.48) and right (x >= 0.48)
    // Let's separate into left and right columns, and sort each top-to-bottom
    var left: [(CGRect, String)] = []
    var right: [(CGRect, String)] = []

    for obs in results {
        if let top = obs.topCandidates(1).first {
            let box = obs.boundingBox
            if box.origin.x < 0.48 {
                left.append((box, top.string))
            } else {
                right.append((box, top.string))
            }
        }
    }

    left.sort { $0.0.origin.y > $1.0.origin.y }
    right.sort { $0.0.origin.y > $1.0.origin.y }

    print("--- LEFT COLUMN ---")
    for (b, s) in left {
        print(String(format: "y:%.3f x:%.3f | %@", b.origin.y, b.origin.x, s))
    }
    print("--- RIGHT COLUMN ---")
    for (b, s) in right {
        print(String(format: "y:%.3f x:%.3f | %@", b.origin.y, b.origin.x, s))
    }
}

for p in [16, 17, 18, 19, 20] {
    ocr(page: p)
}
EOF
