{"description":"Dump detailed OCR data for TOC pages to JSON","code":"const dumpTOC = await tools.bash({
  command: `cat << 'SWIFT' > .work_pdf/dump_toc.swift
import Foundation
import Vision
import AppKit

struct OCRItem: Codable {
    let page: Int
    let text: String
    let x: Double
    let y: Double
    let w: Double
    let h: Double
}

var allItems: [OCRItem] = []

for p in [16, 17, 18, 19, 20] {
    let path = String(format: ".work_pdf/page_%03d.png", p)
    guard let img = NSImage(contentsOfFile: path),
          let tiff = img.tiffRepresentation,
          let rep = NSBitmapImageRep(data: tiff),
          let cg = rep.cgImage else { continue }
    let req = VNRecognizeTextRequest()
    req.recognitionLanguages = ["zh-Hans", "en-US"]
    req.recognitionLevel = .accurate
    let handler = VNImageRequestHandler(cgImage: cg, options: [:])
    try? handler.perform([req])
    for obs in req.results ?? [] {
        if let top = obs.topCandidates(1).first {
            let b = obs.boundingBox
            allItems.append(OCRItem(page: p, text: top.string, x: Double(b.origin.x), y: Double(b.origin.y), w: Double(b.size.width), h: Double(b.size.height)))
        }
    }
}

let encoder = JSONEncoder()
encoder.outputFormatting = .prettyPrinted
if let data = try? encoder.encode(allItems) {
    try? data.write(to: URL(fileURLWithPath: ".work_pdf/toc_ocr.json"))
    print("Dumped \(allItems.count) items to .work_pdf/toc_ocr.json")
}
SWIFT
