{"code":"const parseScript = await tools.bash({
  command: `python3 -c "
import json

with open('.work_pdf/toc_ocr.json') as f:
    items = json.load(f)

for p in [16, 17, 18, 19, 20]:
    print(f'============================== PAGE {p} ==============================')
    for col_name, col_filter in [('LEFT', lambda it: it['x'] < 0.48), ('RIGHT', lambda it: it['x'] >= 0.48)]:
        col_items = [it for it in items if it['page'] == p and col_filter(it)]
        # cluster items by y coordinate within roughly 0.012 vertical tolerance
        col_items.sort(key=lambda it: -it['y'])

        lines = []
        cur_line = []
        cur_y = None
        for it in col_items:
            # ignore header like '目录', '目', '录', 'II目录', '目录III', 'IV 目录', '目录 V'
            if it['text'] in ['目', '录', '目录', 'II目录', '目录III', 'IV 目录', '目录 V', 'II', 'III', 'IV', 'V']:
                continue
            if cur_y is None or abs(it['y'] - cur_y) < 0.014:
                cur_line.append(it)
                cur_y = it['y'] if cur_y is None else (cur_y + it['y'])/2
            else:
                lines.append(cur_line)
                cur_line = [it]
                cur_y = it['y']
        if cur_line:
            lines.append(cur_line)

        print(f'--- {col_name} COLUMN ({len(lines)} lines) ---')
        for l in lines:
            # sort items in line by x
            l.sort(key=lambda it: it['x'])
            combined = ' '.join(it['text'] for it in l)
            print(f'  y={l[0][\"y\"]:.3f}: {combined}')
"`,
  description: "Reconstruct lines from OCR data"
});
return parseScript;
